/** Method ids of sql.remote.Sql. */
export const SqlMethods = {
  service: 'sql.remote.Sql',
  Open: 0x5e00ca0f,
  Exec: 0x9d195726,
  Prepare: 0x77a6b0c6,
  ExecPrepared: 0x259a8893,
  ClosePrepared: 0x5a0a3b54,
  Begin: 0xa8b89584,
  Commit: 0x964889ba,
  Rollback: 0x4ea01e37,
  Describe: 0x0dec78fe,
  State: 0x1becb114,
} as const;

export class SqlClient {
  constructor(readonly rpc: RpcClient) {}

  /**
   * The first call of a session: gets it a database handle. `hints` bit 0: Managed (see ExecInterceptor).
   */
  open(readOnly: boolean, client: string, hints: number, options?: CallOptions): Promise<Opened> {
    return this.rpc.call(SqlMethods.Open, SqlOpenRequest.encode({ readOnly: readOnly, client: client, hints: hints }), Opened.decode, options);
  }

  /**
   * Runs text; the rows of the last statement stream back. `txn` runs it inside that transaction (0 = none).
   */
  exec(text: string, params: ParamListInit, txn: number, options_: ResultOptionsInit, hints: number, options?: CallOptions): RpcStream<resultset.ResultSet, StatementEnd> {
    return this.rpc.stream(SqlMethods.Exec, SqlExecRequest.encode({ text: text, params: params, txn: txn, options: options_, hints: hints }), resultset.ResultSet.decode, options, StatementEnd.decode);
  }

  /**
   * Parses text and keeps it as statement `statement` (chosen by the client).
   */
  prepare(statement: number, text: string, options?: CallOptions): Promise<Prepared> {
    return this.rpc.call(SqlMethods.Prepare, SqlPrepareRequest.encode({ statement: statement, text: text }), Prepared.decode, options);
  }

  execPrepared(statement: number, params: ParamListInit, txn: number, options_: ResultOptionsInit, options?: CallOptions): RpcStream<resultset.ResultSet, StatementEnd> {
    return this.rpc.stream(SqlMethods.ExecPrepared, SqlExecPreparedRequest.encode({ statement: statement, params: params, txn: txn, options: options_ }), resultset.ResultSet.decode, options, StatementEnd.decode);
  }

  closePrepared(statement: number, options?: CallOptions): Promise<void> {
    return this.rpc.call(SqlMethods.ClosePrepared, SqlClosePreparedRequest.encode({ statement: statement }), () => undefined, options);
  }

  begin(txn: number, readOnly: boolean, options?: CallOptions): Promise<Counters> {
    return this.rpc.call(SqlMethods.Begin, SqlBeginRequest.encode({ txn: txn, readOnly: readOnly }), Counters.decode, options);
  }

  commit(txn: number, options?: CallOptions): Promise<Counters> {
    return this.rpc.call(SqlMethods.Commit, SqlCommitRequest.encode({ txn: txn }), Counters.decode, options);
  }

  rollback(txn: number, options?: CallOptions): Promise<Counters> {
    return this.rpc.call(SqlMethods.Rollback, SqlRollbackRequest.encode({ txn: txn }), Counters.decode, options);
  }

  /**
   * The catalog as rows: Tables, Table(name) or Indexes(table).
   */
  describe(what: Catalog, name: string, options_: ResultOptionsInit, options?: CallOptions): RpcStream<resultset.ResultSet, StatementEnd> {
    return this.rpc.stream(SqlMethods.Describe, SqlDescribeRequest.encode({ what: what, name: name, options: options_ }), resultset.ResultSet.decode, options, StatementEnd.decode);
  }

  state(options?: CallOptions): Promise<Counters> {
    return this.rpc.call(SqlMethods.State, SqlStateRequest.encode({  }), Counters.decode, options);
  }

}

